"""Driver for the cube manipulation service. Targets are normalized from measured joint positions."""
from rcb_client import Robot
import numpy as np


def current_action(spec, proprio_row):
    layout = spec['action_types']['joint_position']['layout']
    ranges = np.asarray(spec['action_types']['joint_position']['range_rad'], dtype=float)
    p_layout = spec['proprio_layout']
    qmap = {name[:-4]: float(proprio_row[i]) for i, name in enumerate(p_layout) if name.endswith('_pos')}
    values = []
    for act, (lo, hi) in zip(layout, ranges):
        if act.startswith(('lh_A_', 'rh_A_')):
            name = act.replace('_A_', '_')
            if name.endswith(('FFJ0', 'MFJ0', 'RFJ0', 'LFJ0')):
                q = qmap.get(name[:-1] + '2', 0.0) + qmap.get(name[:-1] + '1', 0.0)
            else:
                q = qmap.get(name, 0.0)
        else:
            q = qmap.get(act, 0.0)
        values.append(2.0 * (q - (lo + hi) / 2.0) / (hi - lo))
    return np.clip(np.asarray(values, dtype=np.float32), -1.0, 1.0)


def close_hand(spec, action, side, amount):
    """Set a cautious wrap grasp; amount 0..1, values are actuator radians."""
    layout = spec['action_types']['joint_position']['layout']
    ranges = spec['action_types']['joint_position']['range_rad']
    prefix = ('lh' if side == 'left' else 'rh') + '_A_'
    physical = {
        'THJ5': 0.20 * amount, 'THJ4': 0.45 * amount,
        'THJ3': 0.05 * amount, 'THJ2': 0.30 * amount, 'THJ1': 0.65 * amount,
    }
    for finger in ('FF', 'MF', 'RF', 'LF'):
        physical[f'{finger}J3'] = 0.52 * amount
        physical[f'{finger}J0'] = 1.25 * amount
    for i, name in enumerate(layout):
        if name.startswith(prefix):
            key = name[len(prefix):]
            if key in physical:
                lo, hi = ranges[i]
                action[i] = 2.0 * (physical[key] - (lo + hi) / 2.0) / (hi - lo)
    return np.clip(action, -1.0, 1.0)


def ramp(start, end, rows):
    return np.asarray([start + (end - start) * ((i + 1) / rows) for i in range(rows)], dtype=np.float32)


def main():
    r = Robot()
    spec = r.spec()
    obs = r.get_obs(cameras=['room_camera'], video='none')
    action = current_action(spec, np.asarray(obs.meta['proprio']['now']))
    target = close_hand(spec, action.copy(), 'left', 0.65)
    actions = ramp(action, target, 25)
    res = r.submit('joint_position', actions, dt=spec['control_dt'], interpolate='hold',
                   cameras=['room_camera'], video='none', note='gradual left-hand curl test')
    res.save('/app/output/curl_test')
    print('status', r.status())
    print('clipped', res.meta.get('clipped'))


if __name__ == '__main__':
    main()
